import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Menu, Search, ShoppingBag, User, Heart, X } from 'lucide-react';
import { AnimatePresence, motion } from 'framer-motion';

export default function Navbar() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const navigate = useNavigate();

  const toggleMenu = () => setIsMenuOpen(!isMenuOpen);
  const toggleSearch = () => setIsSearchOpen(!isSearchOpen);

  return (
    <>
      <header className="fixed top-0 left-0 right-0 z-50 h-16 px-6 md:px-12 flex justify-between items-center bg-[#FDFBF7]/80 backdrop-blur-md border-b border-[#1A1A1A]/5 transition-all duration-500">
        {/* Left: Navigation Controls */}
        <div className="flex items-center gap-8">
          <button onClick={toggleMenu} className="flex items-center gap-3 group">
            <div className="relative w-5 h-5">
               <motion.div 
                 animate={{ rotate: isMenuOpen ? 90 : 0, opacity: isMenuOpen ? 0 : 1 }}
                 className="absolute inset-0"
               >
                 <Menu strokeWidth={1.5} size={20} />
               </motion.div>
               <motion.div 
                 animate={{ rotate: isMenuOpen ? 0 : -90, opacity: isMenuOpen ? 1 : 0 }}
                 className="absolute inset-0"
               >
                 <X strokeWidth={1.5} size={20} />
               </motion.div>
            </div>
            <span className="hidden md:block text-xs uppercase tracking-widest font-medium opacity-60 group-hover:opacity-100 transition-opacity">
              {isMenuOpen ? 'Close' : 'Menu'}
            </span>
          </button>

          <button onClick={toggleSearch} className="hidden md:flex items-center gap-3 group">
            <Search strokeWidth={1.5} size={20} />
            <span className="text-xs uppercase tracking-widest font-medium opacity-60 group-hover:opacity-100 transition-opacity">
              Search
            </span>
          </button>
        </div>

        {/* Center: Brand Identity */}
        <Link to="/" className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2">
          <h1 className="font-serif text-2xl tracking-tight font-bold text-[#1A1A1A]">AETHER</h1>
        </Link>

        {/* Right: Actions */}
        <div className="flex items-center gap-6 md:gap-8">
          <Link to="/contact" className="hidden lg:block text-xs uppercase tracking-widest font-medium opacity-60 hover:opacity-100">
            Concierge
          </Link>
          <Link to="/account" className="hidden md:block opacity-60 hover:opacity-100 transition-opacity">
            <User strokeWidth={1.5} size={20} />
          </Link>
          <button className="opacity-60 hover:opacity-100 transition-opacity">
            <Heart strokeWidth={1.5} size={20} />
          </button>
          <Link to="/cart" className="relative opacity-60 hover:opacity-100 transition-opacity">
            <ShoppingBag strokeWidth={1.5} size={20} />
            <span className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full"></span>
          </Link>
        </div>
      </header>

      {/* Side Menu Overlay */}
      <AnimatePresence>
        {isMenuOpen && (
          <motion.div
            initial={{ x: '-100%' }}
            animate={{ x: 0 }}
            exit={{ x: '-100%' }}
            transition={{ type: 'tween', duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
            className="fixed inset-0 z-40 bg-[#1A1A1A] text-[#FDFBF7] pt-24 px-6 md:px-12 flex flex-col md:flex-row"
          >
            <div className="flex-1 flex flex-col gap-8">
               <nav className="flex flex-col gap-6">
                 {['Shop All', 'Seating', 'Lighting', 'Tables', 'Objects'].map((item) => (
                   <Link 
                     key={item} 
                     to="/shop" 
                     onClick={toggleMenu}
                     className="font-serif text-4xl md:text-6xl hover:text-white/50 transition-colors"
                   >
                     {item}
                   </Link>
                 ))}
               </nav>
            </div>
            <div className="md:w-1/3 mt-12 md:mt-0 border-t md:border-t-0 md:border-l border-white/10 pt-8 md:pl-12">
              <h3 className="text-xs uppercase tracking-widest opacity-50 mb-6">The Brand</h3>
              <div className="flex flex-col gap-4 text-sm opacity-70">
                <Link to="/" onClick={toggleMenu}>Heritage</Link>
                <Link to="/contact" onClick={toggleMenu}>Studios</Link>
                <Link to="/legal/impressum" onClick={toggleMenu}>Legal</Link>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Search Overlay */}
      <AnimatePresence>
        {isSearchOpen && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="fixed top-16 left-0 right-0 z-40 bg-[#FDFBF7] p-12 border-b border-black/5 shadow-xl"
          >
             <div className="max-w-4xl mx-auto">
               <input 
                 type="text" 
                 placeholder="Search for an object..."
                 className="w-full bg-transparent text-4xl font-serif placeholder-neutral-300 border-b border-black/10 pb-4 focus:outline-none focus:border-black transition-colors"
                 autoFocus
               />
               <button 
                onClick={toggleSearch} 
                className="absolute top-8 right-8 p-2 opacity-50 hover:opacity-100"
              >
                <X size={24} strokeWidth={1} />
              </button>
             </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}

